    93  GF_Err gf_isom_box_parse_ex(GF_Box **outBox, GF_BitStream *bs, u32 parent_type, Bool is_root_box)
    94  {
    95          u32 type, uuid_type, hdr_size, restore_type;
    96          u64 size, start, comp_start, end;
    97          char uuid[16];
    98          GF_Err e;
    99          GF_BitStream *uncomp_bs = NULL;
   100          u8 *uncomp_data = NULL;
   101          u32 compressed_size=0;
   102          GF_Box *newBox;
   103          Bool skip_logs = (gf_bs_get_cookie(bs) & GF_ISOM_BS_COOKIE_NO_LOGS ) ? GF_TRUE : GF_FALSE;
   104          Bool is_special = GF_TRUE;
   105
   106          if ((bs == NULL) || (outBox == NULL) ) return GF_BAD_PARAM;
   107          *outBox = NULL;
   108          if (gf_bs_available(bs) < 8) {
   109                  return GF_ISOM_INCOMPLETE_FILE;
   110          }
   111
   112          comp_start = start = gf_bs_get_position(bs);
   113
   114          uuid_type = 0;
   115          size = (u64) gf_bs_read_u32(bs);
   116          hdr_size = 4;
   117          /*fix for some boxes found in some old hinted files*/
   118          if ((size >= 2) && (size <= 4)) {
   119                  size = 4;
   120                  type = GF_ISOM_BOX_TYPE_VOID;
   120                  type = GF_ISOM_BOX_TYPE_VOID;
   121          } else {
   122                  type = gf_bs_read_u32(bs);
   123                  hdr_size += 4;
   124                  /*no size means till end of file - EXCEPT FOR some old QuickTime boxes...*/
   125                  if (type == GF_ISOM_BOX_TYPE_TOTL)
   126                          size = 12;
   127                  if (!size) {
   128                          if (is_root_box) {
   129                                  if (!skip_logs) {
   130                                          GF_LOG(GF_LOG_DEBUG, GF_LOG_CONTAINER, ("[iso file] Warning Read Box type %s (0x%08X) size 0 reading till the end of file\n", gf_4cc_to_str(type), type));
   131                                  }
   132                                  size = gf_bs_available(bs) + 8;
   133                          } else {
   134                                  if (!skip_logs) {
   135                                          GF_LOG(GF_LOG_ERROR, GF_LOG_CONTAINER, ("[iso file] Read Box type %s (0x%08X) at position "LLU" has size 0 but is not at root/file level !\n", gf_4cc_to_str(type), type, start));
   136                                          return GF_ISOM_INVALID_FILE;
   137                                  }
   138                                  return GF_OK;
   139                          }
   140                  }
   141                  if (is_root_box && (size>=8)) {
   142                          Bool do_uncompress = GF_FALSE;
   143                          u8 *compb = NULL;
   144                          u32 osize = 0;
   145                          u32 otype = type;
   146                          if (type==GF_4CC('!', 'm', 'o', 'f')) {
   147                                  do_uncompress = GF_TRUE;
   148                                  type = GF_ISOM_BOX_TYPE_MOOF;
   149                          }
   150                          else if (type==GF_4CC('!', 'm', 'o', 'v')) {
   151                                  do_uncompress = GF_TRUE;
   152                                  type = GF_ISOM_BOX_TYPE_MOOV;
   153                          }
   154                          else if (type==GF_4CC('!', 's', 'i', 'x')) {
   155                                  do_uncompress = GF_TRUE;
   156                                  type = GF_ISOM_BOX_TYPE_SIDX;
   157                          }
   158                          else if (type==GF_4CC('!', 's', 's', 'x')) {
   159                                  do_uncompress = GF_TRUE;
   160                                  type = GF_ISOM_BOX_TYPE_SSIX;
   161                          }
   162
   163                          if (do_uncompress) {
   164                                  compb = gf_malloc((u32) (size-8));
   165
   166                                  compressed_size = (u32) (size - 8);
   167                                  gf_bs_read_data(bs, compb, compressed_size);
   168                                  e = gf_gz_decompress_payload(compb, compressed_size, &uncomp_data, &osize);
   169                                  if (e) {
   170                                          GF_LOG(GF_LOG_ERROR, GF_LOG_CONTAINER, ("[iso file] Failed to uncompress payload for box type %s (0x%08X)\n", gf_4cc_to_str(otype), otype));
   171                                          return e;
   172                                  }
   173
   174                                  //keep size as complete box size for tests below
   175                                  size = osize + 8;
   176                                  uncomp_bs = gf_bs_new(uncomp_data, osize, GF_BITSTREAM_READ);
   177                                  bs = uncomp_bs;
   178                                  start = 0;
   179                                  gf_free(compb);
   180                          }
   336  GF_Err gf_isom_box_parse(GF_Box **outBox, GF_BitStream *bs)
   337  {
   338          return gf_isom_box_parse_ex(outBox, bs, 0, GF_FALSE);
   339  }
