   341  void gf_isom_box_array_reset(GF_List *boxlist)
   342  {
   343          u32 count, i;
   344          if (!boxlist) return;
   345          count = gf_list_count(boxlist);
   346          for (i = 0; i < count; i++) {
   347                  GF_Box *a = (GF_Box *)gf_list_get(boxlist, i);
   348                  if (a) gf_isom_box_del(a);
   349          }
   350  }
   351
   352  void gf_isom_box_array_del(GF_List *boxlist)
   353  {
   354          gf_isom_box_array_reset(boxlist);
   355          gf_list_del(boxlist);
   356  }
   357
   358  void gf_isom_box_array_reset_parent(GF_List **child_boxes, GF_List *boxlist)
   359  {
   360          u32 count, i;
   361          if (!boxlist) return;
   362          count = gf_list_count(boxlist);
   363          for (i = 0; i < count; i++) {
   364                  GF_Box *a = (GF_Box *)gf_list_get(boxlist, i);
   365                  if (a) gf_isom_box_del_parent(child_boxes, a);
   366          }
   367          gf_list_reset(boxlist);
   368  }
   369  void gf_isom_box_array_del_parent(GF_List **child_boxes, GF_List *boxlist)
   370  {
   371          if (!boxlist) return;
   372          gf_isom_box_array_reset_parent(child_boxes, boxlist);
   373          gf_list_del(boxlist);
   374  }
